local ECSComponent = import("Frame.ECS.ECSComponent")
local UIModule = CS.Engine.UI.UIModule
---@class HalloweenQuestComponent
local HalloweenQuestComponent = Class("HalloweenQuestComponent", ECSComponent)
---@type Engine.Modules.CDTimerModule
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local CountDownTime = 2592000 --30 * 86400 30天的秒数

function HalloweenQuestComponent:__init()
    self._uuId = 0     --活动唯一id

    self._poolCallNum = {}               --对应卡池抽取的数量
    self._starInfo = {}                  --所有的三星信息
    self._drawPoolRewards = {}       --领取的对应卡池的奖励信息
    self._gashaponInfo = {}              --玩家副本信息
    self._hpData = {}    --体力恢复
    self._hpLimit = 0
    self.dailyBuyHpTimes = 0
end

function HalloweenQuestComponent:__delete()
    self:CloseTimer()
    self._uuId = 0
    self._poolCallNum = nil
    self._starInfo = nil
    self._drawPoolRewards = nil
    self._gashaponInfo = nil
    self._hpData = nil
    self._hpLimit = nil
    self.dailyBuyHpTimes = nil
end

function HalloweenQuestComponent:SetUuid(activityUuid)
    self._uuId = checkNumber(activityUuid)
end

function HalloweenQuestComponent:Initial(activityUuid, jsonData)
    self._uuId = checkNumber(activityUuid)
    self._gashaponInfo = checkTable(jsonData.gashaponInfo)
    self._poolCallNum = checkTable(jsonData.poolCallNum)
    self._drawPoolRewards = checkTable(jsonData.drawPoolRewards)
    self._hpData = checkTable(jsonData.hpData)
    self._hpLimit = checkNumber(jsonData.hpLimit)
    self.dailyBuyHpTimes = checkNumber(jsonData.dailyBuyHpTimes)
    
    self:StartTimer()
    local curCount = checkNumber(GoodsUtils.GetThingNo(Constants.Currency.JackpotDungeon))
    local deltaCount = jsonData.hpData.hp - curCount
    GoodsUtils.DrawRewards({
        {
            goodsId = Constants.Currency.JackpotDungeon,
            num = checkInt(deltaCount)
        }
    })
    
    
    local t = jsonData.questStar
    if t then
        self._starInfo = {}
        for k, v in pairs(t) do
            local _, conditions = QuestConfMgr:GetInstance():GetQuestConditions(checkString(k))
            if conditions then
                local _t = {}
                local count = 0
                v = table.values(v)
                for m, cdt in pairs(conditions) do
                    count = count + 1
                    _t[checkString(cdt.id)] = (table.keyof(v, count) and 1 or 0) 
                end
                self._starInfo[checkString(k)] = _t
            end
        end
    end
end

--剧情
function HalloweenQuestComponent:ActivityGashaponQuestPlotReq(questId, cb)
    GameUtils.Request(Interfaces.ActivityGashaponQuestPlot, {questId = questId, activityUuid = self:GetUuid()}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        if table.count(jsonData.rewards) > 0 then
            GoodsUtils.DrawRewards(jsonData.rewards)
            CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })
        end

        self._gashaponInfo = checkTable(jsonData.gashaponInfo)
        if cb then
            cb()
        end
    end)
end

--抽奖
function HalloweenQuestComponent:ActivityGashaponQuestChallengeCallReq(poolId, type, cb, drawNum)
    GameUtils.Request(Interfaces.ActivityGashaponQuestChallengeCall, {poolId = poolId, type = type, num = drawNum, activityUuid = self:GetUuid()}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        GoodsUtils.DrawRewards(jsonData.rewards)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })

        self._gashaponInfo = checkTable(jsonData.gashaponInfo)

        if not self._drawPoolRewards[checkString(poolId)] then
            self._drawPoolRewards[checkString(poolId)] = {}
        end
        self._drawPoolRewards[checkString(poolId)] = checkTable(jsonData.callRewardsIds)

        --local num = 0
        --if type == 1 then
        --    num = 1
        --elseif type == 2 then
        --    num = 10
        --end
        self._poolCallNum[checkString(poolId)] = checkNumber(self._poolCallNum[checkString(poolId)]) + checkNumber(drawNum)

        if cb then
            cb()
        end
    end)
end


---UpdateDailyQuestStarInfo 更新星级信息
---@param starInfo table 星级信息
---@param questId string 关卡id
function HalloweenQuestComponent:UpdateDailyQuestStarInfo(questId, starInfo)
    if not starInfo or not questId then
        return
    end
    --达成三星的不刷新
    if not QuestConfMgr:GetInstance():IsCompleteAllCondition(questId) then
        --直接覆盖
        self._starInfo[checkString(questId)] = checkTable(starInfo)
    end
end

---IsCompleteCondition 根据星的条件id判断是否已达成
---@param levelId string 关卡id
---@param conditionId string 条件id
function HalloweenQuestComponent:IsCompleteCondition(levelId, conditionId)
    local levelStarInfo = self._starInfo[checkString(levelId)]
    if levelStarInfo then
        if checkNumber(levelStarInfo[conditionId]) == 1 then
            return true
        end
    end
    return false
end

---IsPassLevelById 是否通关关卡
---@param levelId string 关卡id 
function HalloweenQuestComponent:IsPassLevelById(levelId)
    return checkNumber(self._gashaponInfo.newQuestId) >= checkNumber(levelId)
end

---IsPassPlotLevelById 是否通关关卡
---@param levelId string 关卡id 
function HalloweenQuestComponent:IsPassPlotLevelById(levelId)
    return checkNumber(self._gashaponInfo.newPassedPlotId) >= checkNumber(levelId)
end

function HalloweenQuestComponent:GetUuid()
    return checkNumber(self._uuId)
end

--对应卡池抽取的数量
function HalloweenQuestComponent:GetPoolCallInfo()
    return checkTable(self._poolCallNum)
end

--关卡信息
function HalloweenQuestComponent:GetQuestInfo()
    return checkTable(self._gashaponInfo)
end

function HalloweenQuestComponent:GetDrawPoolRewards()
    return checkTable(self._drawPoolRewards)
end

---UpdateChallengeQuestInfo 更新挑战关卡信息
---@param questId number 关卡id
function HalloweenQuestComponent:UpdateChallengeQuestInfo(questId, starInfo)
    if checkNumber(questId) == 0 then
        return
    end
    if checkNumber(self._gashaponInfo.newQuestId) < checkNumber(questId) then
        self._gashaponInfo.newQuestId = checkNumber(questId)
    end

    if not QuestConfMgr:GetInstance():IsCompleteAllCondition(questId) then
        --直接覆盖
        self._starInfo[checkString(questId)] = checkTable(starInfo)
    end
end

function HalloweenQuestComponent:UpdatePloatQuestInfo(questId)
    if checkNumber(self._gashaponInfo.newPassedPlotId) < checkNumber(questId) then
        self._gashaponInfo.newPassedPlotId = checkNumber(questId)
    end
end

function HalloweenQuestComponent:GetHpLimit()
    return self._hpLimit
end

function HalloweenQuestComponent:GetLastCdTime()
    return self._hpData.lastCdTime
end

function HalloweenQuestComponent:GetParamsNumById(refId, ignore)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6603,"ActivityParamsVo",refId)
    if isNotNull(vo) then
        return isNull(ignore) and checkNumber(vo.num) or vo.num
    end
end

function HalloweenQuestComponent:IsHPFull()
    local curCount = checkNumber(GoodsUtils.GetThingNo(Constants.Currency.JackpotDungeon))
    return curCount >= self._hpLimit
end

---开启定时器
function HalloweenQuestComponent:StartTimer()
    self:CloseTimer()
    self.timer = CDTimerModule.GetInstance():AddCD(1, function(_, _, delta)
        -- 体力已经恢复满，停止倒计时
        if self:IsHPFull() then
            self._hpData.lastCdTime = 0
            --self:BroadcastHPChangeEvent(true, 0, 0)
            self:CloseTimer()
            return
        end
        
        self:SubCDTime(delta)
    
    end, CountDownTime, true, true)
end

---移除定时器
function HalloweenQuestComponent:CloseTimer()
    if isNotNull(self.timer) then
        CDTimerModule.GetInstance():RemoveCD(self.timer)
        self.timer = nil
    end
end

---定时器处理
function HalloweenQuestComponent:SubCDTime(delta)
    self._hpData.lastCdTime = checkNumber(self._hpData.lastCdTime) - checkNumber(delta)
    local recoveryHpPerTime = self:GetParamsNumById(2)
    if self._hpData.lastCdTime <= 0 then
        -- 开始恢复体力
        local recoverCount = recoveryHpPerTime
        
        --printInfo("CHANG DEBUG：实际恢复的体力:" .. checkString(recoverCount))
        GoodsUtils.DrawRewards({
            {
                goodsId = Constants.Currency.JackpotDungeon,
                num = recoverCount
            }
        }, true)
        
        -- 重置倒计时
        self._hpData.lastCdTime = self:GetParamsNumById(1)
        self:StartTimer()
    end
end

function HalloweenQuestComponent:BuyActivityHp()
    if not self:IsActive() then
        GameUtils.Toast(localize("活动已结束"))
        return
    end
    local maxLimit = self._hpLimit
    local num = self:GetParamsNumById(6)
    local consumeGoodsId = self:GetParamsNumById(4)
    local consumeInfo = self:GetParamsNumById(5, true)
    local buyTimes = self:GetBuyTimes()
    local maxBuyLimit = self:GetParamsNumById(7)
    local maxBuyNum = 1
    if checkInt(buyTimes) >= checkInt(maxBuyLimit) then
        maxBuyNum = 0
    end
    local consumeData = parse_strings(consumeInfo)
    local consumeNum = consumeData[buyTimes + 1] or consumeData[#consumeData]
    local prices = {{currency = checkInt(consumeGoodsId), current = checkInt(consumeNum)}}
    local activityTips = localize('今日剩余兑换次数: _num_', {_num_ = checkInt(maxBuyLimit) - buyTimes})
    local consume = {goodsId = consumeGoodsId, num = consumeNum}
    
    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
        goodsId        = self:GetParamsNumById(8),
        goodsNum       = num,
        isShowNum      = true,
        maxHaveNum     = checkInt(maxLimit),
        prices         = prices,
        maxBuyNum      = maxBuyNum,
        activityTips   = activityTips,
        buyCb          = function (price, buyNum)
            GameUtils.Request(Interfaces.ActivityGashaponQuestBuyHp, {consume = table.serialize(consume), activityUuid = self:GetUuid()}, function(request, response)
                local showRewards = clone(response.data.rewards)
                table.insert(response.data.rewards, {
                    goodsId = consumeGoodsId,
                    num = -consumeNum
                })
                GoodsUtils.DrawRewards(response.data.rewards, true)
                self._hpData = checkTable(response.data.hpInfo)
                self.dailyBuyHpTimes = checkInt(self.dailyBuyHpTimes) + 1
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = showRewards } })
            end)
        end
    }})
end

---@return integer 返回已经购买次数
function HalloweenQuestComponent:GetBuyTimes()
    return self.dailyBuyHpTimes
end

function HalloweenQuestComponent:IsActive()
    ---@type ActivityComponent
    local activityComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.ActivityComponent)
    local dojo = activityComponent:GetDojoByActivityId(self:GetUuid())
    if dojo then
        ---@type ActivityUtils
        local ActivityUtils         = import("Game.Activity.ActivityUtils")
        return ActivityUtils.IsActivityEnabled(dojo)
    end
    return false
end

return HalloweenQuestComponent